/* 3. Poll-capture into static buffer (left channel mono) */

n = 0;

{
  uint32_t spin_sample;
  uint32_t spin_total = 0;
  bool timed_out = false;

  while (n < want)
    {
      spin_sample = 0;

      for (;;)
        {
          uint32_t status = aud_getreg(AUD_FIFO_STATUS);

          if (!(status & AUD_ADC_FIFO_EMPTY))
            {
              break;
            }

          if (++spin_sample >= FIFO_SPIN_LIMIT)
            {
              timed_out = true;
              break;
            }
        }

      if (timed_out)
        {
          break;
        }

      uint32_t sample = aud_getreg(AUD_ADC_FIFO_PORT);

      g_mic_test_pcm[n] = (int16_t)(sample & 0xffff);
      n++;

      spin_total += spin_sample;

      if (spin_total >= TOTAL_SPIN_CAP)
        {
          syslog(LOG_ERR,
                 "[mic] TIMEOUT after %d samples "
                 "(spin_total=%lu >= %lu)\n"
                 "  AUD_FIFO_STATUS = 0x%08lx\n"
                 "  AUD_CONFIG      = 0x%08lx\n",
                 n, (unsigned long)spin_total,
                 (unsigned long)TOTAL_SPIN_CAP,
                 (unsigned long)aud_getreg(AUD_FIFO_STATUS),
                 (unsigned long)aud_getreg(AUD_CONFIG));
          timed_out = true;
          break;
        }
    }

  if (timed_out && n == 0)
    {
      syslog(LOG_ERR, "[mic] no samples captured, aborting\n");
      audio_deinit();
      return 0;
    }

  if (timed_out)
    {
      syslog(LOG_WARNING,
             "[mic] timeout after %d/%d samples — partial result\n",
             n, want);
    }
}

